sys_script_include.script:
var HSBCTradeCaseException = Class.create();
HSBCTradeCaseException.prototype = {
    initialize: function() {},
    createHsbcTradeCase: function(objectid, status, additional_attributes, payload, objectversion, eventtype, objectidtype, objecttype, bpiValue, messageid, source) {
        var createTradeCase = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');
        var mssMOCSGrpID = gs.getProperty("HSBC_MOCS_Group");
        createTradeCase.setValue("assignment_group", mssMOCSGrpID);
        createTradeCase.short_description = "Case Created for Trade ID - " + objectid.getDisplayValue() + " for the Status - " + status.getDisplayValue();           //Case created for is_exception = true
        createTradeCase.financial_object = objectid;
        createTradeCase.trade_status = status;
        createTradeCase.u_fo_process_status = status;
        createTradeCase.u_additional_attributes = additional_attributes;
        createTradeCase.u_payload = payload;
        createTradeCase.u_objectversion = objectversion;
        createTradeCase.u_event_type = eventtype;
        createTradeCase.u_objectidtype = objectidtype;
        createTradeCase.u_object_type = objecttype;
        createTradeCase.u_business_process_instance.setDisplayValue(bpiValue);
        createTradeCase.u_message_id = messageid;
        createTradeCase.u_source = source;
        var newobjectid = createTradeCase.insert();     

    },
    type: 'HSBCTradeCaseException'
};
